var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3a_scen.gd")
var t = H.unit("U_RHINO_A").models[0]
var worst := 0.0
for m in H.unit("U_INTERCESSOR_SQUAD_A").models:
	var p = m.position
	var rr = TransportManager.is_position_within_disembark_range(Vector2(float(p.x), float(p.y)), m, H.unit("U_RHINO_A"), 3.0)
	worst = maxf(worst, float(rr.get("farthest_inches", 0.0)))
return worst > 3.0 and worst < 4.0
